/bin/bash -lc "python - <<'PY'
import json
import api, core, model, service, render

# Pipeline type, rendering, and algorithm behavior.
r = service.compute([{'a':[1,2]}, [['add','/a/1',9], ['replace','/a/0',3]])
assert isinstance(r, model.Result)
assert json.loads(render.present(r)) == {'ok': True, 'document': {'a':[3,9,2]}}
assert core.solve([{'x':1}, [['remove',''], ['add','/a',2]]]) == {'ok':False,'document':{'x':1}}
assert core.solve([[1,2], [['add','/-',3]]) == {'ok':True,'document':[1,2,3]}

# Transactions, equality, errors, and idempotency (including cached begin).
payload = [
 {'op':'put','key':'z','input':[{'n':1}, []], 'id':'p'},
 {'op':'begin','id':'b'},
 {'op':'put','key':'z','input':[{'n':2}, []]},
 {'op':'rollback'},
 {'op':'get','key':'z'},
 {'op':'expect','key':'z','value':{'ok':True,'document':{'n':1}}},
 {'op':'begin','id':'b'},
 {'op':'begin','id':'b','extra':0},
 {'op':'commit'},
 {'op':'get'},
 {'op':'list'},
]
out=json.loads(api.run(json.dumps(payload)))
assert out['events'][1] == {'ok':1}
assert out['events'][3] == {'ok':0}
assert out['events'][4] == {'ok':{'ok':True,'document':{'n':1}}}
assert out['events'][5] == {'ok':True}
assert out['events'][6] == {'ok':1}  # replay, no push
assert out['events'][7] == {'error':'id-conflict'}
assert out['events'][8] == {'ok':0}
assert out['events'][9] == {'error':'command'}
assert out['depth'] == 0

# Empty key, nested snapshots and bool/int JSON equality.
out=json.loads(api.run(json.dumps([
 {'op':'put','key':'','input':[0,[]]}, {'op':'expect','key':'','value':{'ok':True,'document':False}},
 {'op':'begin'}, {'op':'delete','key':''}, {'op':'rollback'}, {'op':'list'}
])))
assert out['events'][1] == {'ok':True}
assert out['events'][-1]['ok'][0][0] == ''
print('focused checks passed')
PY"

